CREATE TABLE `contract_accelerations` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `investor_id` bigint unsigned NOT NULL,
  `investment_request_id` bigint unsigned NOT NULL,
  `contract_period_id` bigint unsigned DEFAULT NULL,
  `original_days` int NOT NULL,
  `acceleration_percentage` decimal(5,2) NOT NULL DEFAULT '5.00',
  `days_to_reduce` decimal(20,6) NOT NULL DEFAULT (0),
  `capital_released` decimal(15,2) DEFAULT '0.00',
  `new_duration` decimal(20,6) NOT NULL DEFAULT (0),
  `applied` tinyint(1) NOT NULL DEFAULT '0',
  `bonus_amount` decimal(20,6) DEFAULT (0),
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `fk_accelerations_investor` (`investor_id`),
  KEY `fk_accelerations_request` (`investment_request_id`),
  KEY `fk_accelerations_period` (`contract_period_id`),
  CONSTRAINT `fk_accelerations_investor` FOREIGN KEY (`investor_id`) REFERENCES `investors` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_accelerations_period` FOREIGN KEY (`contract_period_id`) REFERENCES `contract_periods` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_accelerations_request` FOREIGN KEY (`investment_request_id`) REFERENCES `investment_requests` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=485 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
