--
-- Table structure for table `contract_histories`
--

DROP TABLE IF EXISTS `contract_histories`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `contract_histories` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `investor_id` bigint unsigned NOT NULL,
  `paquete_inversion_id` bigint unsigned DEFAULT NULL,
  `contract_period_id` bigint unsigned DEFAULT NULL,
  `fecha_inicio` date NOT NULL,
  `fecha_fin` date NOT NULL,
  `dias_contrato` int DEFAULT NULL,
  `total_contrato` decimal(15,2) NOT NULL,
  `tasa_interes` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `acciones_otorgadas` int NOT NULL DEFAULT '0',
  `valor_total_acciones` decimal(15,2) NOT NULL DEFAULT '0.00',
  `porcentaje_participacion_accionista` decimal(8,5) NOT NULL DEFAULT '0.00000',
  `rendimiento_aprobado_mensual` decimal(5,2) NOT NULL DEFAULT '0.00',
  `rentabilidad_contrato` decimal(15,2) NOT NULL DEFAULT '0.00',
  `rendimiento_total_contrato` decimal(15,2) NOT NULL DEFAULT '0.00',
  `liquidacion_diaria_capital` decimal(15,2) NOT NULL DEFAULT '0.00',
  `liquidacion_diaria_rendimiento` decimal(15,2) NOT NULL DEFAULT '0.00',
  `rendimiento_total_generado` decimal(15,2) NOT NULL DEFAULT '0.00',
  `rendimiento_total_pagado` decimal(15,2) NOT NULL DEFAULT '0.00',
  `motivo` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `observaciones` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=136 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

