-- Table structure for table `credit_increase_requests`
--

DROP TABLE IF EXISTS `credit_increase_requests`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `credit_increase_requests` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `weekly_credit_id` bigint unsigned NOT NULL,
  `requested_amount` decimal(15,2) NOT NULL,
  `status` enum('pending','approved','rejected') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `admin_notes` text COLLATE utf8mb4_unicode_ci,
  `reviewed_by` bigint unsigned DEFAULT NULL,
  `reviewed_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `credit_increase_requests_weekly_credit_id_foreign` (`weekly_credit_id`),
  KEY `credit_increase_requests_reviewed_by_foreign` (`reviewed_by`),
  CONSTRAINT `credit_increase_requests_reviewed_by_foreign` FOREIGN KEY (`reviewed_by`) REFERENCES `users` (`id`),
  CONSTRAINT `credit_increase_requests_weekly_credit_id_foreign` FOREIGN KEY (`weekly_credit_id`) REFERENCES `weekly_credits` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
