DROP TABLE IF EXISTS `disparador_tipo_bonificacion`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `disparador_tipo_bonificacion` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `disparador_id` bigint unsigned NOT NULL,
  `tipo_bonificacion_id` bigint unsigned NOT NULL,
  `condiciones` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin COMMENT 'Condiciones específicas para esta relación',
  `activo` tinyint(1) NOT NULL DEFAULT '1',
  `prioridad` int NOT NULL DEFAULT '0' COMMENT 'Orden de ejecución',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `disparador_tipo_unique` (`disparador_id`,`tipo_bonificacion_id`),
  KEY `disparador_tipo_bonificacion_disparador_id_activo_index` (`disparador_id`,`activo`),
  KEY `disparador_tipo_bonificacion_tipo_bonificacion_id_activo_index` (`tipo_bonificacion_id`,`activo`),
  CONSTRAINT `disparador_tipo_bonificacion_disparador_id_foreign` FOREIGN KEY (`disparador_id`) REFERENCES `disparadores` (`id`) ON DELETE CASCADE,
  CONSTRAINT `disparador_tipo_bonificacion_tipo_bonificacion_id_foreign` FOREIGN KEY (`tipo_bonificacion_id`) REFERENCES `tipos_bonificaciones` (`id`) ON DELETE CASCADE,
  CONSTRAINT `disparador_tipo_bonificacion_chk_1` CHECK (json_valid(`condiciones`))
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
