DROP TABLE IF EXISTS `user_sales`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `user_sales` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint unsigned NOT NULL,
  `investor_id` bigint unsigned NOT NULL,
  `monto` decimal(15,2) NOT NULL,
  `clasificacion` enum('nuevo','reinversion','referido') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'nuevo',
  `referido_por_investor_id` bigint unsigned DEFAULT NULL,
  `comision_porcentaje` decimal(5,2) NOT NULL DEFAULT '0.00',
  `comision_monto` decimal(15,2) NOT NULL DEFAULT '0.00',
  `detalles_particion` json DEFAULT NULL,
  `observaciones` text COLLATE utf8mb4_unicode_ci,
  `comprobantes` json DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `user_sales_investor_id_unique` (`investor_id`),
  KEY `user_sales_user_id_foreign` (`user_id`),
  KEY `user_sales_referido_por_investor_id_foreign` (`referido_por_investor_id`),
  CONSTRAINT `user_sales_investor_id_foreign` FOREIGN KEY (`investor_id`) REFERENCES `investors` (`id`) ON DELETE CASCADE,
  CONSTRAINT `user_sales_referido_por_investor_id_foreign` FOREIGN KEY (`referido_por_investor_id`) REFERENCES `investors` (`id`) ON DELETE SET NULL,
  CONSTRAINT `user_sales_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
